<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$db=$GLOBALS['pdo'];$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$like='%'.$q.'%';$st=$db->prepare('SELECT COUNT(*) FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id LEFT JOIN workspaces w ON w.id=a.workspace_id WHERE a.action LIKE ? OR COALESCE(u.name,"") LIKE ? OR COALESCE(w.name,"") LIKE ?');$st->execute([$like,$like,$like]);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/40));$page=min($page,$pages);$st=$db->prepare('SELECT a.*,u.name actor_name,w.name workspace_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id LEFT JOIN workspaces w ON w.id=a.workspace_id WHERE a.action LIKE ? OR COALESCE(u.name,"") LIKE ? OR COALESCE(w.name,"") LIKE ? ORDER BY a.created_at DESC LIMIT 40 OFFSET ?');$st->bindValue(1,$like);$st->bindValue(2,$like);$st->bindValue(3,$like);$st->bindValue(4,($page-1)*40,PDO::PARAM_INT);$st->execute();$logs=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='admin';datanix_header('Admin audit logs','logs',$layout);
?>
<div class="admin-kicker">SECURITY &amp; OPERATIONS</div><h1 class="admin-page-title">Audit log</h1><p class="admin-page-desc">Tindakan administratif, akses dan perubahan data tercatat. Isi log tidak memuat baris dataset mentah atau secret koneksi.</p><form class="admin-filter-row" method="get"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Cari tindakan, admin, workspace"><button class="btn btn-primary btn-sm">Cari</button></form><section class="admin-card"><div class="admin-card-head"><strong><?=e(format_number($total))?> event</strong><span class="admin-badge">Paginated</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Time</th><th>Actor</th><th>Workspace</th><th>Action</th><th>Entity</th><th>Safe metadata</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e(date('d M Y H:i:s',strtotime($log['created_at'])))?></td><td><?=e($log['actor_name']??'System')?></td><td><?=e($log['workspace_name']??'—')?></td><td><strong><?=e($log['action'])?></strong></td><td><?=e($log['entity_type']??'—')?> <?=e($log['entity_id']??'')?></td><td><code><?=e($log['metadata_json']??'—')?></code></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="6" class="text-center text-muted">Belum ada event.</td></tr><?php endif;?></tbody></table></div><div class="admin-pagination"><span>Page <?=e($page)?> / <?=e($pages)?></span><span><?php if($page>1):?><a class="btn btn-light-outline btn-sm" href="?q=<?=e(rawurlencode($q))?>&amp;page=<?=$page-1?>">← Prev</a><?php endif;?> <?php if($page<$pages):?><a class="btn btn-light-outline btn-sm" href="?q=<?=e(rawurlencode($q))?>&amp;page=<?=$page+1?>">Next →</a><?php endif;?></span></div></section>
